export interface CopilotChatPayload {
  messages: Array<{
    role: 'user' | 'assistant';
    text: string;
    attachments?: Array<{
      name: string;
      type: string;
      base64?: string;
    }>;
  }>;
  pageContext?: CopilotPageContext;
}

export async function handleCopilotChat(payload: CopilotChatPayload | CopilotChatPayload['messages']): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
  consultedInstructions?: string[];
}> {
  const messages = Array.isArray(payload) ? payload : (payload?.messages || []);
  const pageContext = Array.isArray(payload) ? undefined : payload?.pageContext;
  const lastMessage = messages[messages.length - 1];

  const rawText = (lastMessage?.text || (lastMessage as any)?.content || '').trim();
  if (!lastMessage || !rawText) {
    return {
      text: "Olá! Sou Sophia, a Inteligência Artificial e Co-pilot Científica da Busca Acadêmica Integrada UNILA. Como posso te auxiliar em sua pesquisa, busca de artigos ou informações sobre a UNILA e editais hoje?"
    };
  }

  const normPrompt = normalizeText(rawText);

  // 1. Cálculos matemáticos diretos (resposta imediata sem latência)
  const mathRes = trySolveMathExpression(rawText);
  if (mathRes !== null) {
    return { text: mathRes };
  }

  // Se a mensagem for "quanto é?", "quanto dá?", "qual o resultado?" e a mensagem anterior tinha conta
  if (normPrompt === "quanto e" || normPrompt === "quanto da" || normPrompt === "qual o resultado" || normPrompt === "resultado") {
    const prevMsg = messages && messages.length > 1 ? messages[messages.length - 2]?.text : '';
    if (prevMsg) {
      const prevMath = trySolveMathExpression(prevMsg);
      if (prevMath !== null) {
        return { text: prevMath };
      }
    }
  }

  // 2. Conhecimentos gerais imediatos factuais (invenções, datas históricas, capitais)
  const directGenKnowledge = resolveGeneralKnowledgeQuery(rawText, normPrompt);
  if (directGenKnowledge !== null) {
    return { text: directGenKnowledge };
  }

  // 3. Executar via modelo LLM (Gemini) com Function Calling e ferramentas ativas
  const llmResult = await tryExecuteLlmProvider(messages, pageContext);
  if (llmResult) {
    return llmResult;
  }

  // 4. Motor Dinâmico Baseado em APIs Reais (UNILA Editais API, Harvester Acadêmico, UNILA News API e Wikipedia/Crossref API)
  // Gera respostas 100% dinâmicas sem respostas prontas ou estáticas.
  return handleDynamicApiEngine(messages, pageContext);
}

/**
 * Executa requisição via Gemini API (cotas gratuitas do AI Studio)
 */
async function tryExecuteLlmProvider(
  messages: CopilotChatPayload['messages'],
  pageContext?: CopilotChatPayload['pageContext']
): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
} | null> {
  const ai = getAiClient();
  if (!ai) return null;

  try {
    const lastMsg = messages[messages.length - 1];
    const rawUserPrompt = (lastMsg?.text || (lastMsg as any)?.content || '').trim();
    const lowerPrompt = rawUserPrompt.toLowerCase();
    const normPrompt = normalizeText(rawUserPrompt);
    const isSimple = isSimpleQuestion(rawUserPrompt, normPrompt);

    // Constrói o contexto da página apenas se NÃO for pergunta simples
    let contextSummary = '';
    if (pageContext && !isSimple) {
      const parts: string[] = [];
      parts.push(`[ESTADO ATUAL DA PÁGINA DA APLICAÇÃO]:
- Idioma da Interface: ${pageContext.currentLanguage || 'pt'}
- Status da Pesquisa: ${pageContext.hasSearched ? `Pesquisa ATIVA pelo termo: "${pageContext.currentQuery || ''}"` : 'Tela Inicial (aguardando pesquisa)'}
- Resultados na Tela: ${pageContext.resultsCount || 0} artigos filtrados de um total de ${pageContext.totalFound || 0} encontrados nas bases
- Bases Científicas Selecionadas: ${pageContext.selectedSources ? pageContext.selectedSources.join(', ') : 'Todas'}
- Filtros Ativos: Acesso Aberto = ${pageContext.openAccessOnly ? 'Ativo' : 'Inativo'}, PDF Direto = ${pageContext.hasPdfOnly ? 'Ativo' : 'Inativo'}, Ordenação = ${pageContext.sortBy || 'relevance'}, Anos = ${pageContext.yearRange?.from || 'início'} até ${pageContext.yearRange?.to || 'atual'}
- Filtros Adicionais: Idiomas = ${pageContext.selectedLanguages?.join(', ') || 'Todos'}, Áreas = ${pageContext.selectedFields?.join(', ') || 'Todas'}
- Coleção de Artigos Salvos: ${pageContext.savedCount || 0} artigos`);

      if (pageContext.activeArticle) {
        parts.push(`\n[ARTIGO ATUALMENTE ABERTO OU SELECIONADO NA TELA]:
- Título: "${pageContext.activeArticle.title}"
- Autores: ${pageContext.activeArticle.authors?.map(a => a.name).join(', ') || 'Autoria não indicada'}
- Ano: ${pageContext.activeArticle.year || 's.d.'} | Periódico/Base: ${pageContext.activeArticle.venue || pageContext.activeArticle.source} | DOI: ${pageContext.activeArticle.doi || 'N/A'}
- Resumo Analítico: ${pageContext.activeArticle.abstract || 'Sem resumo fornecido'}`);
      }

      if (pageContext.savedArticles && pageContext.savedArticles.length > 0) {
        parts.push(`\n[COLEÇÃO DE ARTIGOS SALVOS PELO USUÁRIO (Top ${Math.min(pageContext.savedArticles.length, 5)})]:\n` +
          pageContext.savedArticles.slice(0, 5).map((a, idx) => 
            `(${idx + 1}) "${a.title}" (${a.year || 's.d.'}) por ${a.authors?.map(aut => aut.name).join(', ')}. Base: ${a.source || 'N/A'}. DOI: ${a.doi || 'N/A'}.\nResumo: ${a.abstract ? a.abstract.slice(0, 300) : 'Sem resumo'}`
          ).join('\n\n')
        );
      } else if (pageContext.visibleArticles && pageContext.visibleArticles.length > 0) {
        parts.push(`\n[ARTIGOS VISÍVEIS NA LISTAGEM ATUAL DA PÁGINA (Top ${Math.min(pageContext.visibleArticles.length, 10)})]:\n` +
          pageContext.visibleArticles.slice(0, 10).map((a, idx) => 
            `(${idx + 1}) "${a.title}" (${a.year || 's.d.'}) por ${a.authors?.map(aut => aut.name).join(', ')}. Base: ${a.source || 'N/A'}. DOI: ${a.doi || 'N/A'}.\nResumo: ${a.abstract ? a.abstract.slice(0, 300) : 'Sem resumo'}`
          ).join('\n\n')
        );
      }

      contextSummary = parts.join('\n');
    }

    // Para perguntas simples, mantemos histórico mínimo para máxima velocidade e concisão
    const effectiveMessages = isSimple ? messages.slice(-4) : messages.slice(-10);
    const rawContents: any[] = [];

    for (let i = 0; i < effectiveMessages.length; i++) {
      const msg = effectiveMessages[i];
      const parts: any[] = [];
      if (i === effectiveMessages.length - 1 && contextSummary) {
        parts.push({ text: `${contextSummary}\n\n${msg.text}` });
      } else {
        parts.push({ text: msg.text });
      }

      if (msg.attachments && msg.attachments.length > 0) {
        for (const att of msg.attachments) {
          if (att.base64 && att.type) {
            parts.push({
              inlineData: {
                mimeType: att.type,
                data: att.base64.replace(/^data:[^;]+;base64,/, '')
              }
            });
          }
        }
      }

      rawContents.push({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts
      });
    }

    // Garante que o primeiro turno é 'user' e que os papéis alternam estritamente
    const contents: any[] = [];
    for (const turn of rawContents) {
      if (contents.length === 0 && turn.role === 'model') {
        continue; // Descarta mensagem inicial do assistente para iniciar com 'user'
      }
      if (contents.length > 0 && contents[contents.length - 1].role === turn.role) {
        // Mescla partes consecutivas com o mesmo papel
        contents[contents.length - 1].parts.push(...turn.parts);
      } else {
        contents.push(turn);
      }
    }

    if (contents.length === 0) {
      contents.push({ role: 'user', parts: [{ text: rawUserPrompt || 'Olá' }] });
    }

    // Estratégia de resiliência: gemini-3.8-flash como modelo primário padrão, com fallback ágil para gemini-flash-latest e gemini-3.1-flash-lite
    const executionPlan = [
      { model: 'gemini-3.8-flash', delayMs: 0, timeoutMs: 9000 },
      { model: 'gemini-flash-latest', delayMs: 150, timeoutMs: 8000 },
      { model: 'gemini-3.1-flash-lite', delayMs: 150, timeoutMs: 7000 }
    ];
    
    // Ferramentas do Copilot sempre disponíveis para a IA decidir autonomamente
    const shouldUseTools = true;

    for (let attempt = 0; attempt < executionPlan.length; attempt++) {
      const step = executionPlan[attempt];
      if (step.delayMs > 0) {
        await new Promise(r => setTimeout(r, step.delayMs));
      }
      const model = step.model;
      try {
        const abortController = new AbortController();
        const timeoutId = setTimeout(() => abortController.abort(), step.timeoutMs || 8000);

        const config: any = {
          systemInstruction: BASE_SYSTEM_INSTRUCTION,
          temperature: isSimple ? 0.1 : 0.2,
          abortSignal: abortController.signal
        };
        if (shouldUseTools) {
          config.tools = COPILOT_TOOLS;
        }

        try {
          const response = await ai.models.generateContent({
            model,
            contents,
            config
          });
          clearTimeout(timeoutId);

          if (response) {
            return await processLlmToolCallsAndResponse(ai, model, contents, response, messages, pageContext, isSimple);
          }
        } finally {
          clearTimeout(timeoutId);
        }
      } catch (callErr: any) {
        const errMsg = callErr?.message || '';
        console.warn(`Tentativa ${attempt + 1} (${model}) falhou:`, errMsg.slice(0, 140));
      }
    }
  } catch (err: any) {
    console.error("Erro no provedor LLM:", err);
  }

  return null;
}

/**
 * Processa chamadas de função retornadas pela LLM de forma iterativa e modular
 */
async function processLlmToolCallsAndResponse(
  ai: GoogleGenAI,
  activeModel: string,
  initialContents: any[],
  initialResponse: any,
  messages: CopilotChatPayload['messages'],
  pageContext?: CopilotChatPayload['pageContext'],
  isSimple: boolean = false
): Promise<{
  text: string;
  articles?: UnifiedArticle[];
  editais?: UnilaEdital[];
  actions?: CopilotAction[];
  consultedInstructions?: string[];
}> {
  const actions: CopilotAction[] = [];
  let retrievedArticles: UnifiedArticle[] = [];
  let retrievedEditais: UnilaEdital[] = [];
  let assistantText = initialResponse?.text || '';
  const consultedInstructions: string[] = [];

  const lastUserMsg = messages[messages.length - 1];
  const rawUserPrompt = (lastUserMsg?.text || (lastUserMsg as any)?.content || '').trim();
  const lowerPrompt = rawUserPrompt.toLowerCase();
  const normPrompt = normalizeText(rawUserPrompt);
  const shouldHighlight = isExplicitHighlightRequest(rawUserPrompt, lowerPrompt, normPrompt);
  const shouldListArticles = isExplicitArticleRequest(rawUserPrompt, lowerPrompt, normPrompt);

  let currentResponse = initialResponse;
  let currentContents = [...initialContents];
  const MAX_TOOL_TURNS = 5;

  for (let turn = 0; turn < MAX_TOOL_TURNS; turn++) {
    const candidates = currentResponse?.candidates || [];
    const candidateContent = candidates[0]?.content;
    const functionCalls: any[] = [];
    for (const cand of candidates) {
      for (const part of cand.content?.parts || []) {
        if (part.functionCall) {
          functionCalls.push(part.functionCall);
        }
      }
    }

    if (currentResponse?.text) {
      assistantText = currentResponse.text;
    }

    // Se não há chamadas de função neste turno, a IA concluiu o raciocínio
    if (functionCalls.length === 0) {
      break;
    }

    const functionResponses: any[] = [];

    for (const call of functionCalls) {
      const { name, args } = call;

      if (name === 'consult_behavior_instruction') {
        const requestedName = ((args?.instruction_name as string) || '').trim();
        const reason = ((args?.reason as string) || '').trim();
        const module = getBehaviorInstruction(requestedName);

        if (module) {
          consultedInstructions.push(module.id);
          functionResponses.push({
            functionResponse: {
              name,
              response: {
                status: "loaded",
                instruction_name: module.id,
                title: module.title,
                summary: module.summary,
                behavior_content: module.content,
                guidance: "Extensão de comportamento carregada com sucesso. Avalie se este conteúdo é suficiente e relevante para estruturar sua resposta final. Se precisar de outra extensão complementar (ex: 'epistemologia_falibilista', 'orientacao_interface_seletores', 'redacao_abnt_tcc', 'institucional_editais_unila', 'analise_artigo_metodologia', 'formatacao_pdf_modal') ou se precisar consultar novamente, chame a ferramenta novamente quantas vezes forem necessárias antes de emitir a resposta final."
              }
            }
          });
        } else {
          functionResponses.push({
            functionResponse: {
              name,
              response: {
                status: "not_found",
                requested_name: requestedName,
                available_instructions: Object.keys(BEHAVIOR_INSTRUCTIONS),
                guidance: `A instrução '${requestedName}' não foi encontrada no catálogo. Avalie a lista de extensões disponíveis: [${Object.keys(BEHAVIOR_INSTRUCTIONS).join(', ')}] e consulte a extensão adequada se for relevante.`
              }
            }
          });
        }
      } else if (name === 'search_academic_repositories') {
        const query = (args?.query as string) || '';
        const limit = typeof args?.limit === 'number' ? args.limit : 4;

        try {
          const searchRes = await executeFederatedSearch(
            query,
            ['OpenAlex', 'arXiv', 'DOAJ', 'Europe PMC', 'Crossref', 'Semantic Scholar', 'CORE'],
            true
          );
          retrievedArticles = searchRes.articles.slice(0, limit);

          // Registra ação para atualizar a pesquisa na página da aplicação e exibir o feedback visual
          actions.push({
            type: 'EXECUTE_SEARCH',
            description: `Pesquisa realizada: "${query}"`,
            payload: { query }
          });

          functionResponses.push({
            functionResponse: {
              name,
              response: {
                totalFound: searchRes.articles.length,
                query,
                displayedCount: retrievedArticles.length,
                articles: retrievedArticles.map(a => ({
                  title: a.title,
                  authors: a.authors.slice(0, 3).map(au => au.name).join(', '),
                  year: a.year,
                  sources: a.sources.join(', '),
                  hasPdf: Boolean(a.openAccess?.pdfUrl || a.urls?.pdfUrl),
                  pdfUrl: a.openAccess?.pdfUrl || a.urls?.pdfUrl || null,
                  doiUrl: a.urls?.doiUrl || (a.doi ? `https://doi.org/${a.doi}` : null),
                  downloadUrl: a.openAccess?.pdfUrl || a.urls?.pdfUrl || a.urls?.doiUrl || null
                }))
              }
            }
          });
        } catch (searchErr: any) {
          console.error("Co-pilot search error:", searchErr);
          functionResponses.push({
            functionResponse: { name, response: { error: "Falha na busca acadêmica", query } }
          });
        }
      } else if (name === 'search_unila_editais') {
        const query = (args?.query as string) || '';
        const category = args?.category as string;
        try {
          const editais = await fetchUnilaEditais(query, category, 6);
          retrievedEditais = editais;
          functionResponses.push({
            functionResponse: {
              name,
              response: {
                totalFound: editais.length,
                query,
                editais: editais.map(e => ({
                  title: e.title,
                  category: e.category,
                  unit: e.unit,
                  publishDate: e.publishDate
                }))
              }
            }
          });
        } catch (edErr: any) {
          console.error("Co-pilot editais error:", edErr);
          functionResponses.push({
            functionResponse: { name, response: { error: "Falha na consulta de editais", query } }
          });
        }
      } else if (name === 'highlight_element') {
        actions.push({
          type: 'HIGHLIGHT_ELEMENT',
          description: `Destacou: ${args?.title || args?.elementId}`,
          payload: {
            elementId: args?.elementId,
            title: args?.title || 'Destaque',
            description: args?.description || '',
            contextNote: args?.contextNote || '',
            quickPrompts: Array.isArray(args?.quickPrompts) ? args.quickPrompts : []
          }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, highlightedElement: args?.elementId }
          }
        });
      } else if (name === 'execute_page_search') {
        const query = (args?.query as string) || '';
        actions.push({
          type: 'EXECUTE_SEARCH',
          description: `Pesquisa realizada: "${query}"`,
          payload: {
            query,
            semantic: args?.semantic,
            openAccessOnly: args?.openAccessOnly,
            hasPdfOnly: args?.hasPdfOnly
          }
        });

        // Também recupera artigos para exibir no chat se ainda não estiverem preenchidos
        if (retrievedArticles.length === 0 && query) {
          try {
            const searchRes = await executeFederatedSearch(
              query,
              ['OpenAlex', 'arXiv', 'DOAJ', 'Europe PMC', 'Crossref', 'Semantic Scholar', 'CORE'],
              true
            );
            retrievedArticles = searchRes.articles.slice(0, 4);
          } catch (e) {
            console.warn("execute_page_search federated retrieval error:", e);
          }
        }

        functionResponses.push({
          functionResponse: {
            name,
            response: { 
              success: true, 
              executedQuery: query,
              resultsCount: retrievedArticles.length,
              articlesFound: retrievedArticles.map(a => ({ title: a.title, year: a.year, authors: a.authors.map(au => au.name).join(', ') }))
            }
          }
        });
      } else if (name === 'filter_page_results') {
        actions.push({
          type: 'FILTER_PAGE_RESULTS',
          description: 'Filtros da pesquisa atualizados',
          payload: {
            openAccessOnly: args?.openAccessOnly,
            hasPdfOnly: args?.hasPdfOnly,
            semanticMode: args?.semanticMode,
            yearFrom: args?.yearFrom,
            yearTo: args?.yearTo,
            sortBy: args?.sortBy,
            selectedSources: args?.selectedSources,
            selectedLanguages: args?.selectedLanguages,
            selectedFields: args?.selectedFields,
            clearFilters: args?.clearFilters
          }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, updatedFilters: args }
          }
        });
      } else if (name === 'change_page_language') {
        const lang = (args?.language || 'pt').toLowerCase().trim();
        actions.push({
          type: 'CHANGE_PAGE_LANGUAGE',
          description: `Alterou idioma da página para ${lang.toUpperCase()}`,
          payload: { language: lang }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, newLanguage: lang, message: `O idioma da interface foi alterado para ${lang.toUpperCase()}` }
          }
        });
      } else if (name === 'open_view') {
        if (args?.view === 'saved') actions.push({ type: 'OPEN_SAVED' });
        else if (args?.view === 'methodology') actions.push({ type: 'OPEN_METHODOLOGY' });
        else if (args?.view === 'sources') actions.push({ type: 'OPEN_SOURCES_STATUS' });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, openedView: args?.view }
          }
        });
      } else if (name === 'guide_platform_tour') {
        actions.push({
          type: 'START_TOUR',
          payload: { tourTopic: args?.tourTopic || 'geral' }
        });
        functionResponses.push({
          functionResponse: {
            name,
            response: { success: true, startedTour: args?.tourTopic }
          }
        });
      } else if (name === 'read_article_full_content') {
        const queryOrDoi = ((args?.identifierOrQuery as string) || '').toLowerCase().trim();
        let matched: any = pageContext?.activeArticle && (
          pageContext.activeArticle.title.toLowerCase().includes(queryOrDoi) ||
          (pageContext.activeArticle.doi && pageContext.activeArticle.doi.toLowerCase().includes(queryOrDoi))
        ) ? pageContext.activeArticle : null;

        if (!matched && pageContext?.savedArticles) {
          matched = pageContext.savedArticles.find(a => 
            a.title.toLowerCase().includes(queryOrDoi) ||
            (a.doi && a.doi.toLowerCase().includes(queryOrDoi))
          ) || null;
        }

        if (!matched && pageContext?.visibleArticles) {
          matched = pageContext.visibleArticles.find(a => 
            a.title.toLowerCase().includes(queryOrDoi) ||
            (a.doi && a.doi.toLowerCase().includes(queryOrDoi))
          ) || null;
        }

        if (!matched) {
          try {
            const liveRes = await executeFederatedSearch(queryOrDoi, ['OpenAlex', 'Crossref', 'Europe PMC'], true);
            if (liveRes.articles.length > 0) {
              const f = liveRes.articles[0];
              matched = {
                id: f.id,
                title: f.title,
                authors: f.authors,
                year: f.year,
                venue: f.venue,
                doi: f.doi,
                abstract: f.abstract || '',
                source: f.sources?.[0],
                citationCount: f.citationCount,
                pdfUrl: f.urls?.pdfUrl || f.openAccess?.pdfUrl
              };
            }
          } catch (e) {
            console.error("Erro ao ler artigo completo:", e);
          }
        }

        if (matched) {
          actions.push({
            type: 'SELECT_ARTICLE',
            description: `Leu e analisou artigo: "${matched.title}"`,
            payload: {
              articleId: matched.id,
              title: matched.title
            }
          });
        }

        functionResponses.push({
          functionResponse: {
            name,
            response: matched ? {
              found: true,
              title: matched.title,
              authors: matched.authors?.map((a: any) => a.name).join(', ') || 'N/A',
              year: matched.year,
              venue: matched.venue || matched.source,
              doi: matched.doi,
              pdfUrl: matched.pdfUrl || matched.openAccess?.pdfUrl || matched.urls?.pdfUrl || null,
              downloadUrl: matched.pdfUrl || matched.openAccess?.pdfUrl || matched.urls?.pdfUrl || (matched.doi ? `https://doi.org/${matched.doi}` : null),
              abstract: matched.abstract || 'Resumo analítico disponível.',
              citationCount: matched.citationCount,
              fullTextSummary: `Artigo científico examinado. Autores: ${matched.authors?.map((a: any) => a.name).join(', ')}. Resumo: ${matched.abstract}`
            } : {
              found: false,
              message: `Não foi possível recuperar o texto completo para o termo "${queryOrDoi}".`
            }
          }
        });
      }
    }

    // Envia o resultado das ferramentas de volta para a IA avaliar e continuar se necessário
    if (candidateContent && functionResponses.length > 0) {
      currentContents = [
        ...currentContents,
        candidateContent,
        {
          role: 'user',
          parts: functionResponses
        }
      ];

      try {
        const nextRes = await ai.models.generateContent({
          model: activeModel,
          contents: currentContents,
          config: {
            systemInstruction: BASE_SYSTEM_INSTRUCTION,
            tools: COPILOT_TOOLS,
            temperature: isSimple ? 0.1 : 0.2
          }
        });

        currentResponse = nextRes;
        if (nextRes && nextRes.text) {
          assistantText = nextRes.text;
        }
      } catch (turnErr: any) {
        console.warn(`Erro no turno ${turn + 2} de execução das ferramentas da IA:`, turnErr?.message);
        break;
      }
    } else {
      break;
    }
  }

  // Síntese dinâmica caso o modelo não tenha emitido texto final
  if (!assistantText) {
    if (retrievedEditais.length > 0) {
      assistantText = `Consultei o portal oficial de documentos e editais da UNILA e selecionei ${retrievedEditais.length} editais relevantes para você. Veja as opções para consulta e download abaixo:`;
    } else if (shouldListArticles && retrievedArticles.length > 0) {
      assistantText = `Encontrei ${retrievedArticles.length} publicações acadêmicas diretamente nas bases científicas integradas. Você pode visualizar os resumos e abrir os PDFs a seguir:`;
    } else if (actions.length > 0 && actions[0].description) {
      assistantText = `${actions[0].description} diretamente na tela da plataforma!`;
    } else {
      assistantText = "Ação executada com sucesso na interface.";
    }
  }

  return {
    text: assistantText,
    articles: (shouldListArticles && retrievedArticles.length > 0) ? retrievedArticles : undefined,
    editais: retrievedEditais.length > 0 ? retrievedEditais : undefined,
    actions: actions.length > 0 ? actions : undefined,
    consultedInstructions: consultedInstructions.length > 0 ? Array.from(new Set(consultedInstructions)) : undefined
  };
}

/**
 * Resolve expressões matemáticas simples enviadas pelo usuário
 */
function trySolveMathExpression(input: string): string | null {
  if (!input) return null;
  const clean = input.toLowerCase()
    .replace(/quanto\s+[eé](\s+o\s+resultado\s+de)?/gi, '')
    .replace(/qual\s+[eé]\s+o\s+resultado\s+de/gi, '')
    .replace(/calcule/gi, '')
    .replace(/[?!=]/g, '')
    .replace(/,/g, '.')
    .replace(/x/gi, '*')
    .trim();

  if (/^[-+*/%^().\d\s]+$/.test(clean) && /\d/.test(clean)) {
    try {
      const sanitized = clean.replace(/[^0-9+\-*/().]/g, '');
      if (sanitized && !/[a-zA-Z_$]/.test(sanitized)) {
        const result = Function(`"use strict"; return (${sanitized})`)();
        if (typeof result === 'number' && !isNaN(result) && isFinite(result)) {
          return `O resultado do cálculo é **${result}**. Se precisar de outros cálculos ou quiser relacioná-los aos seus estudos, conte comigo!`;
        }
      }
    } catch {}
  }
  return null;
}

/**
 * Detecta se a pergunta do usuário é uma questão simples/curta/factual
 * ou amenidade que requer explicação em poucas palavras (sem ser seca e sem ser extensa).
 * Pedidos de explicação aprofundada, artigos ou análises retornam false para permitir respostas mais detalhadas.
 */
function isSimpleQuestion(prompt: string, norm: string): boolean {
  // Pedidos expressos de destaque ou listagem de artigos devem ter acesso completo a ferramentas
  if (isExplicitHighlightRequest(prompt, prompt.toLowerCase(), norm)) return false;
  if (isExplicitArticleRequest(prompt, prompt.toLowerCase(), norm)) return false;

  // Questões com pedidos de explicação aprofundada, detalhamento ou temas acadêmicos complexos NUNCA são tratadas como simples
  if (
    norm.includes("explique") ||
    norm.includes("explicar") ||
    norm.includes("explicacao") ||
    norm.includes("detalhe") ||
    norm.includes("detalhes") ||
    norm.includes("detalhad") ||
    norm.includes("aprofund") ||
    norm.includes("analise") ||
    norm.includes("resenha") ||
    norm.includes("fichamento") ||
    norm.includes("artigo") ||
    norm.includes("papers") ||
    norm.includes("tcc") ||
    norm.includes("metodologia") ||
    norm.includes("revisao de literatura") ||
    norm.includes("estado da arte") ||
    norm.includes("comparativo") ||
    norm.includes("pesquisa cientifica")
  ) {
    return false;
  }

  // Contas matemáticas
  if (trySolveMathExpression(prompt) !== null) return true;
  if (/^[\d\s+\-*/xX.=,()^%?]+$/.test(prompt)) return true;
  if (norm.startsWith("quanto e") || norm.startsWith("quanto da") || norm.startsWith("qual o resultado") || norm.startsWith("calcule")) return true;

  const words = prompt.trim().split(/\s+/).filter(Boolean);
  if (words.length <= 14) {
    if (
      norm.startsWith("o que e") ||
      norm.startsWith("o que sao") ||
      norm.startsWith("qual e") ||
      norm.startsWith("qual a") ||
      norm.startsWith("quais sao") ||
      norm.startsWith("quem e") ||
      norm.startsWith("quem foi") ||
      norm.startsWith("onde fica") ||
      norm.startsWith("onde esta") ||
      norm.startsWith("como fazer") ||
      norm.startsWith("quantos") ||
      norm.startsWith("quantas") ||
      norm.startsWith("o que voce acha") ||
      norm.startsWith("o que acha") ||
      norm.startsWith("voce gosta") ||
      norm.includes("velocidade da luz") ||
      norm.includes("distancia") ||
      norm.includes("futebol") ||
      norm.includes("bolo") ||
      norm.includes("receita") ||
      norm.includes("capital") ||
      norm.includes("populacao") ||
      norm.includes("horario") ||
      norm.includes("hora")
    ) {
      return true;
    }
  }
  if (words.length <= 6 && !norm.includes("artigo") && !norm.includes("edital") && !norm.includes("tcc")) {
    return true;
  }
  return false;
}

