    return {
      text: "A **UNILA** (Universidade Federal da Integração Latino-Americana) é uma universidade pública federal sediada em Foz do Iguaçu (PR), fundada em 2010 com a missão de promover a integração solidária, científica e cultural da América Latina e do Caribe, com ensino bilíngue (português e espanhol)."
    };
