function extractSearchKeywords(text: string, stopWords: string[]): string {
  const words = text
    .replace(/[^\w\s-]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopWords.includes(w.toLowerCase()));
  return words.slice(0, 4).join(' ');
}

function extractCleanAcademicQuery(prompt: string): string {
  const removePatterns = [
    /^(busque|buscar|busca|pesquise|pesquisar|pesquisa|procure|procurar|procura|encontre|ache|mostre|exiba)\s+(artigos?\s+(sobre|de|do|da)?|papers?\s+(sobre|de|do|da)?|estudos?\s+(sobre|de|do|da)?)/i,
    /^(artigos?\s+(sobre|de|do|da)?)/i,
    /^(papers?\s+(sobre|de|do|da)?)/i,
    /^(estudos?\s+(sobre|de|do|da)?)/i,
    /^(quero\s+ver\s+artigos?\s+(sobre|de|do|da)?)/i,
    /^(quais\s+(são\s+os\s+)?artigos?\s+(sobre|de|do|da)?)/i,
    /^(busque|buscar|busca|pesquise|pesquisar|pesquisa|procure|procurar|procura)\s+(por\s+)?/i,
    /\b(no\s+chat|aqui\s+no\s+chat|por\s+favor|pra\s+mim)\b/gi
  ];

  let cleaned = prompt.trim();
  for (const pat of removePatterns) {
    cleaned = cleaned.replace(pat, '').trim();
  }

  return cleaned.replace(/[?.!]+$/, '').trim();
}

function normalizeText(text: string): string {
  return (text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s]/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractConceptTerm(lower: string): string {
  const match = lower.match(/(?:o que [eé]|o que significa|conceito de|defini[çc][aã]o de|explique|como funciona)\s+([a-zA-ZÀ-ÿ\s]{3,40})/i);
  if (match && match[1]) {
    const term = match[1].trim().replace(/(?:na ciência|na pesquisa|acad[eê]mico|\?)/gi, '').trim();
    const conversationalStopWords = [
      'oi', 'ola', 'olá', 'isso', 'aquilo', 'voce', 'você', 'sophia', 'unila',
      'multirrepositorio', 'multirrepositório', 'ajuda', 'pesquisa', 'tudo', 'nada',
      'bom dia', 'boa tarde', 'boa noite', 'um artigo', 'um paper', 'a unila', 'o portal'
    ];
    if (conversationalStopWords.includes(term.toLowerCase()) || term.length < 3) {
      return '';
    }
    return term;
  }
  return '';
}
