import { AcademicSource, UnifiedArticle } from '../types.js';
import { removeDiacritics } from './bm25.js';

/**
 * Normaliza um DOI para o formato padrao canonico (ex: "10.1000/182")
 */
export function normalizeDoi(doi: string | null | undefined): string | null {
  if (!doi) return null;
  const clean = doi
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\/(dx\.)?doi\.org\//i, '')
    .replace(/^doi:\s*/i, '')
    .replace(/[>\]\)\.,;]+$/, '');
  
  return clean.startsWith('10.') ? clean : null;
}

/**
 * Normaliza um titulo para correspondencia difusa (remove simbolos, espacos extras e pontuacao)
 */
export function normalizeTitle(title: string): string {
  if (!title) return '';
  return removeDiacritics(title)
    .replace(/<[^>]*>/g, '') // remove tags HTML e formatacap
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Calcula similaridade de strings (coeficiente de Dice baseado em bigramas de caracyeres)
 */
export function stringSimilarity(strA: string, strB: string): number {
  if (strA === strB) return 1.0;
  if (!strA || !strB) return 0;
  if (strA.length < 2 || strB.length < 2) return 0;

  const getBigrams = (str: string) => {
    const s = str.replace(/\s+/g, '');
    const set = new Map<string, number>();
    for (let i = 0; i < s.length - 1; i++) {
      const bi = s.slice(i, i + 2);
      set.set(bi, (set.get(bi) || 0) + 1);
    }
    return set;
  };

  const mapA = getBigrams(strA);
  const mapB = getBigrams(strB);

  let intersection = 0;
  let totalA = 0;
  let totalB = 0;

  for (const [, count] of mapA) totalA += count;
  for (const [, count] of mapB) totalB += count;

  for (const [bi, countA] of mapA) {
    const countB = mapB.get(bi);
    if (countB) {
      intersection += Math.min(countA, countB);
    }
  }

  return (2.0 * intersection) / (totalA + totalB);
}

/**
 * Motor de Desduplicação Canônica e Fusão de Metadados Acadêmicos
 * 
 * =========================================================================================
 * O DESAFIO DE FUSIONAR DADOS DE 8 BASES DISTINTAS:
 * =========================================================================================
 * Quando consultamos OpenAlex, Crossref, Semantic Scholar, Europe PMC, arXiv, DOAJ, CORE e CAPES
 * em paralelo, um mesmo artigo pode retornar 3 ou 4 vezes com ligeiras variações:
 * - O Crossref tem o DOI exato e a contagem de referências, mas às vezes não fornece o abstract.
 * - O Europe PMC traz o abstract completo e link direto para o PDF no PubMed Central.
 * - O OpenAlex traz contagem de citações global atualizada e lista de afiliações normalizada.
 * - O arXiv traz a versão preprint sem DOI formal definitivo.
 * 
 * Este algoritmo executa uma fusão inteligente em dois estágios:
 * 1. Resolução Estrita por DOI: Normaliza variações (https://doi.org/, maiúsculas, pontuação)
 *    para identificar univocamente o mesmo trabalho científico.
 * 2. Similaridade Fuzzy de Título (Sørensen–Dice bigram >= 0.88 com tolerância de ano <= 1):
 *    Captura artigos sem DOI indexado (como teses da BDTD/CAPES e preprints do arXiv) que
 *    compartilham título quase idêntico ao de uma publicação formal.
 * 
 * Fusão de Metadados: Ao identificar uma duplicata, não descartamos os dados; unificamos o melhor
 * de cada base (maior contagem de citações, abstract mais completo, PDF aberto garantido e
 * listagem de todas as bases onde o artigo foi encontrado).
 */
export function deduplicateArticles(articles: UnifiedArticle[]): UnifiedArticle[] {
  const unifiedList: UnifiedArticle[] = [];
  const doiMap = new Map<string, number>(); // doi -> indice na lista unificada

  for (const current of articles) {
    const currentDoi = normalizeDoi(current.doi);
    const normTitle = normalizeTitle(current.title);

    let matchIndex = -1;

    // 1. Correspondemcia exata por DOI
    if (currentDoi && doiMap.has(currentDoi)) {
      matchIndex = doiMap.get(currentDoi)!;
    } else {
      // 2. Correspondencia aproximada por Titulo e Autor
      for (let i = 0; i < unifiedList.length; i++) {
        const existing = unifiedList[i];
        const existingNormTitle = normalizeTitle(existing.title);

        // Verificacao rapida de proporcao de comprimento
        const lenRatio = Math.min(normTitle.length, existingNormTitle.length) / Math.max(normTitle.length, existingNormTitle.length);
        if (lenRatio < 0.7) continue;

        const sim = stringSimilarity(normTitle, existingNormTitle);
        if (sim >= 0.88) {
          // Verifica ano ou autor quabdo disponivel
          const yearDiff = (current.year && existing.year) ? Math.abs(current.year - existing.year) : 0;
          if (yearDiff <= 1) {
            matchIndex = i;
            break;
          }
        }
      }
    }

    if (matchIndex >= 0) {
      // Funde no artigo ja existente
      const existing = unifiedList[matchIndex];
      unifiedList[matchIndex] = mergeTwoArticles(existing, current);
      if (currentDoi && !doiMap.has(currentDoi)) {
        doiMap.set(currentDoi, matchIndex);
      }
    } else {
      // Novo artigo distinto
      const newIndex = unifiedList.length;
      unifiedList.push(current);
      if (currentDoi) {
        doiMap.set(currentDoi, newIndex);
      }
    }
  }

  return unifiedList;
}

/**
 * Unifica duas representacoes duplicadas do mesmo artigo cientifico
 */
function mergeTwoArticles(target: UnifiedArticle, source: UnifiedArticle): UnifiedArticle {
  // Combina o conjunto de fontes academicas
  const mergedSources = Array.from(new Set([...target.sources, ...source.sources])) as AcademicSource[];

  // Escolhe o melhor resumo (privilegia texto mais longo e completo)
  const abstract = (source.abstract && source.abstract.length > (target.abstract?.length || 0))
    ? source.abstract
    : (target.abstract || source.abstract || '');

  // Escolhe o melhor titulo (privilegia capitalizacao adequada, sem caixa alta total)
  const title = (source.title && target.title === target.title.toUpperCase() && source.title !== source.title.toUpperCase())
    ? source.title
    : (target.title || source.title);

  // Informacoes mais completas de acesso aberto
  const isOpen = target.openAccess.isOpen || source.openAccess.isOpen;
  const pdfUrl = target.openAccess.pdfUrl || source.openAccess.pdfUrl;
  const oaStatus = target.openAccess.status !== 'closed' && target.openAccess.status !== 'unknown'
    ? target.openAccess.status
    : source.openAccess.status;

  // Maximo de citacoes encontradas
  const citationCount = Math.max(target.citationCount || 0, source.citationCount || 0);

  // Uniao de palavras-chave e areas de estudo
  const fieldsOfStudy = Array.from(new Set([...target.fieldsOfStudy, ...source.fieldsOfStudy]));
  const keywords = Array.from(new Set([...target.keywords, ...source.keywords]));

  // Autores (prioriza os registros que trazem dados de afiliacao institucional)
  const hasAffiliationTarget = target.authors.some(a => a.affiliation);
  const hasAffiliationSource = source.authors.some(a => a.affiliation);
  const authors = hasAffiliationSource && !hasAffiliationTarget && source.authors.length > 0
    ? source.authors
    : (target.authors.length > 0 ? target.authors : source.authors);

  // URLs consolidadas
  const urls = {
    doiUrl: target.urls.doiUrl || source.urls.doiUrl,
    pdfUrl: target.urls.pdfUrl || source.urls.pdfUrl || pdfUrl || undefined,
    landingPage: target.urls.landingPage || source.urls.landingPage
  };

  // Detalhes especificos de cada fonte
  const sourceDetails = {
    ...target.sourceDetails,
    ...source.sourceDetails
  };

  return {
    ...target,
    title,
    doi: target.doi || source.doi,
    abstract,
    venue: target.venue || source.venue,
    year: target.year || source.year,
    publicationDate: target.publicationDate || source.publicationDate,
    publisher: target.publisher || source.publisher,
    publicationType: target.publicationType !== 'other' ? target.publicationType : source.publicationType,
    authors,
    citationCount,
    fieldsOfStudy,
    keywords,
    sources: mergedSources,
    sourceDetails,
    openAccess: {
      isOpen,
      status: oaStatus || 'unknown',
      pdfUrl: pdfUrl || null,
      license: target.openAccess.license || source.openAccess.license
    },
    urls,
    score: {
      bm25: Math.max(target.score.bm25, source.score.bm25),
      morphologicalMatch: Math.max(target.score.morphologicalMatch, source.score.morphologicalMatch),
      semanticCosine: Math.max(target.score.semanticCosine || 0, source.score.semanticCosine || 0),
      finalRelevance: Math.max(target.score.finalRelevance, source.score.finalRelevance),
      matchedTerms: Array.from(new Set([...target.score.matchedTerms, ...source.score.matchedTerms]))
    }
  };
}
