import "dotenv/config";
import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { executeFederatedSearch } from "./server/harvester.js";
import { handleCopilotChat } from "./server/copilot.js";
import { fetchUnilaEditais, fetchUnilaNews } from "./server/unila_service.js";
import { AcademicSource } from "./src/types.js";

async function startServer() {
  const app = express();
  const PORT = 3000;

  // Habilita CORS para permitir que requisições vindas de clientes externos (ex: GitHub Pages) funcionem
  app.use((req, res, next) => {
    res.header("Access-Control-Allow-Origin", "*");
    res.header("Access-Control-Allow-Methods", "GET, POST, OPTIONS, PUT, DELETE");
    res.header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept, Authorization");
    if (req.method === "OPTIONS") {
      return res.sendStatus(200);
    }
    next();
  });

  // Permite cargas maiores para upload de imagens base64 multimodais e documemtos
  app.use(express.json({ limit: "25mb" }));

  // Verificacao de saude do servivo (health check)
  app.get("/api/health", (_req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  });

  // Endpoint do Chatbot Co-pilot com IA
  app.post("/api/copilot", async (req, res) => {
    try {
      const { messages, pageContext } = req.body;
      if (!messages || !Array.isArray(messages)) {
        return res.status(400).json({ error: "Parâmetro 'messages' é obrigatório e deve ser uma lista." });
      }

      const result = await handleCopilotChat({ messages, pageContext });
      res.json(result);
    } catch (error: any) {
      console.error("Copilot API error:", error);
      res.status(500).json({
        text: "Desculpe, ocorreu um erro ao processar sua solicitação no co-pilot. Por favor, tente novamente.",
        error: error?.message
      });
    }
  });

  // Endpoint de editais oficiais da UNILA (https://documentos.unila.edu.br e https://portal.unila.edu.br/editais)
  app.get("/api/unila/editais", async (req, res) => {
    try {
      const q = (req.query.q as string || '').trim();
      const cat = (req.query.category as string || '').trim();
      const limit = parseInt(req.query.limit as string || '10', 10);
      const editais = await fetchUnilaEditais(q, cat, limit);
      res.json({ editais, count: editais.length, source: "https://documentos.unila.edu.br" });
    } catch (err: any) {
      console.error("Unila Editais API error:", err);
      res.status(500).json({ error: "Falha ao recuperar editais", message: err?.message });
    }
  });

  // Endpoint de notícias do portal institucional da UNILA (https://portal.unila.edu.br/noticias)
  app.get("/api/unila/news", async (req, res) => {
    try {
      const q = (req.query.q as string || '').trim();
      const limit = parseInt(req.query.limit as string || '6', 10);
      const news = await fetchUnilaNews(q, limit);
      res.json({ news, count: news.length, source: "https://portal.unila.edu.br/noticias" });
    } catch (err: any) {
      console.error("Unila News API error:", err);
      res.status(500).json({ error: "Falha ao recuperar notícias", message: err?.message });
    }
  });

  // Endpoint de proxy para visualizador de PDF embutido sem bloqueio de CORS ou X-Frame-Options
  app.get("/api/pdf-proxy", async (req, res) => {
    const targetUrl = req.query.url as string;
    if (!targetUrl || !targetUrl.startsWith("http")) {
      return res.status(400).send("URL de PDF inválida");
    }

    try {
      const upstreamRes = await fetch(targetUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36",
          "Accept": "application/pdf,application/octet-stream,*/*"
        },
        redirect: "follow",
        signal: AbortSignal.timeout(20000)
      });

      if (!upstreamRes.ok) {
        return res.status(upstreamRes.status).send(`Falha ao recuperar PDF da fonte externa: HTTP ${upstreamRes.status}`);
      }

      const contentType = upstreamRes.headers.get("content-type") || "application/pdf";
      res.setHeader("Content-Type", contentType.includes("pdf") ? "application/pdf" : contentType);
      res.setHeader("Content-Disposition", 'inline; filename="artigo.pdf"');
      res.setHeader("Access-Control-Allow-Origin", "*");
      res.removeHeader("X-Frame-Options");
      res.removeHeader("Content-Security-Policy");

      const arrayBuffer = await upstreamRes.arrayBuffer();
      res.send(Buffer.from(arrayBuffer));
    } catch (err: any) {
      console.warn("PDF proxy error for URL:", targetUrl, err?.message);
      res.status(502).send("Não foi possível carregar o PDF diretamente: " + (err?.message || "Timeout na conexão"));
    }
  });

  // API de busca academica 
  app.get("/api/search", async (req, res) => {
    try {
      const query = (req.query.q as string || '').trim();
      const sourcesParam = req.query.sources as string;
      const semanticParam = req.query.semantic === 'true';

      let selectedSources: AcademicSource[] = [
        'Portal CAPES',
        'Semantic Scholar',
        'OpenAlex',
        'Crossref',
        'CORE',
        'Europe PMC',
        'arXiv',
        'DOAJ'
      ];

      if (sourcesParam) {
        const parsed = sourcesParam.split(',').map(s => s.trim()) as AcademicSource[];
        if (parsed.length > 0) {
          selectedSources = parsed;
        }
      }

      const startTime = Date.now();
      const searchQuery = query || 'inteligência artificial';

      const result = await executeFederatedSearch(
        searchQuery,
        selectedSources,
        semanticParam
      );

      const executionTimeMs = Date.now() - startTime;

      res.json({
        query: searchQuery,
        totalFound: result.totalFound,
        deduplicatedCount: result.deduplicatedCount,
        executionTimeMs,
        sourcesStatus: result.sourcesStatus,
        articles: result.articles,
        facets: result.facets
      });
    } catch (error: any) {
      console.error("Search error:", error);
      res.status(500).json({
        error: "Falha ao processar busca",
        message: error?.message || "Erro interno"
      });
    }
  });

  // Serve arquivos estáticos das pastas public e images diretamente com Content-Type correto
  app.use(express.static(path.join(process.cwd(), 'public')));
  app.use('/images', express.static(path.join(process.cwd(), 'images')));

  // Monta o middleware do Vite para desenvolvimento ou serve a pasta dist em producao
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (_req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Federated Academic Search running on http://localhost:${PORT}`);
  });
}

startServer();
