/**
 * Consulta conceito científico/enciclopédico via Wikipedia API em Português
 * com validação semântica e rejeição de artigos irrelevantes/revistas de celebridades.
 */
export async function fetchScientificConcept(term: string): Promise<{
  title: string;
  extract: string;
  url: string;
} | null> {
  const cleanTerm = term.trim();
  if (!cleanTerm || cleanTerm.length < 3) return null;

  // Evita buscar pronomes, verbos vazios ou saudações
  if (STOP_WORDS_SET.has(cleanTerm.toLowerCase())) return null;

  const trySummary = async (pageTitle: string): Promise<{ title: string; extract: string; url: string } | null> => {
    try {
      const encoded = encodeURIComponent(pageTitle);
      const res = await fetch(
        `https://pt.wikipedia.org/api/rest_v1/page/summary/${encoded}`,
        { headers: { 'User-Agent': 'UNILA-Academic-Search/2.0' } }
      );
      if (!res.ok) return null;
      const data = await res.json();
      
      if (data.type === 'disambiguation') return null;
      if (data.extract) {
        const lowerExtract = data.extract.toLowerCase();
        // Rejeita páginas de desambiguação e veículos de entretenimento/fofoca (ex: Revista Quem)
        if (
          lowerExtract.includes('pode referir-se a:') ||
          lowerExtract.includes('pode se referir a:') ||
          lowerExtract.includes('desambiguação') ||
          lowerExtract.includes('é uma revista') ||
          lowerExtract.includes('foi uma revista') ||
          lowerExtract.includes('é um álbum de') ||
          lowerExtract.includes('é uma telenovela') ||
          lowerExtract.includes('é um telejornal') ||
          lowerExtract.includes('é uma canção gravada')
        ) {
          return null;
        }

        return {
          title: data.title,
          extract: data.extract,
          url: data.content_urls?.desktop?.page || `https://pt.wikipedia.org/wiki/${encoded}`
        };
      }
    } catch {
      // Ignora erro
    }
    return null;
  };

  // 1. Tenta resumo direto pelo termo
  const direct = await trySummary(cleanTerm);
  if (direct) return direct;

  // 2. Se falhar ou for ambíguo, tenta buscar via API de busca da Wikipedia
  try {
    const searchUrl = `https://pt.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(cleanTerm)}&format=json&utf8=1&srlimit=4`;
    const searchRes = await fetch(searchUrl, { headers: { 'User-Agent': 'UNILA-Academic-Search/2.0' } });
    if (searchRes.ok) {
      const searchData = await searchRes.json();
      const hits = searchData.query?.search || [];
      for (const hit of hits) {
        if (!hit.title || STOP_WORDS_SET.has(hit.title.toLowerCase())) continue;
        const result = await trySummary(hit.title);
        if (result) return result;
      }
    }
  } catch {
    // Ignora erro de busca
  }

  return null;
}

