// 5. Coletor arXiv (analisador de feed Atom XML)
async function harvestArXiv(query: string): Promise<FetchSourceResult> {
  const startTime = Date.now();
  const source: AcademicSource = 'arXiv';
  try {
    const url = `https://export.arxiv.org/api/query?search_query=all:${encodeURIComponent(query)}&start=0&max_results=25`;
    const res = await fetchWithTimeout(url);
    if (!res.ok) return handleSourceResponseError(source, res, startTime);
    const xml = await res.text();

    const articles: UnifiedArticle[] = [];
    const entryRegex = /<entry>([\s\S]*?)<\/entry>/g;
    let match;

    while ((match = entryRegex.exec(xml)) !== null) {
      const entryXml = match[1];

      const idMatch = /<id>([^<]+)<\/id>/.exec(entryXml);
      const titleMatch = /<title>([\s\S]*?)<\/title>/.exec(entryXml);
      const summaryMatch = /<summary>([\s\S]*?)<\/summary>/.exec(entryXml);
      const publishedMatch = /<published>([^<]+)<\/published>/.exec(entryXml);
      const doiMatch = /<arxiv:doi>([^<]+)<\/arxiv:doi>/.exec(entryXml);
      const pdfMatch = /<link[^>]*title="pdf"[^>]*href="([^"]+)"/.exec(entryXml);

      const authors: { name: string }[] = [];
      const authorRegex = /<author>\s*<name>([^<]+)<\/name>/g;
      let aMatch;
      while ((aMatch = authorRegex.exec(entryXml)) !== null) {
        authors.push({ name: aMatch[1].trim() });
      }

      // Categprias tematicas do pre-print
      const categories: string[] = [];
      const catRegex = /<category[^>]*term="([^"]+)"/g;
      let cMatch;
      while ((cMatch = catRegex.exec(entryXml)) !== null) {
        categories.push(cMatch[1]);
      }

      const rawId = idMatch ? idMatch[1].trim() : '';
      const arxivId = rawId.replace('http://arxiv.org/abs/', '').replace('https://arxiv.org/abs/', '');
      const pubYear = publishedMatch ? parseInt(publishedMatch[1].slice(0, 4), 10) : null;
      const cleanTitle = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : 'Sem título';
      const cleanSummary = summaryMatch ? summaryMatch[1].replace(/\s+/g, ' ').trim() : '';
      const doi = doiMatch ? normalizeDoi(doiMatch[1]) : null;
      const pdfUrl = pdfMatch ? pdfMatch[1] : (arxivId ? `https://arxiv.org/pdf/${arxivId}.pdf` : null);

      articles.push({
        id: `arxiv-${arxivId || Math.random().toString(36).substring(2, 8)}`,
        doi,
        title: cleanTitle,
        authors,
        year: pubYear,
        publicationDate: publishedMatch ? publishedMatch[1].slice(0, 10) : undefined,
        abstract: cleanSummary,
        venue: 'arXiv e-Print Archive',
        publicationType: 'preprint',
        openAccess: {
          isOpen: true,
          status: 'green',
          pdfUrl,
          license: 'arXiv Non-exclusive distribution license'
        },
        citationCount: 0,
        fieldsOfStudy: categories.length > 0 ? categories.slice(0, 4) : ['Física', 'Ciência da Computação', 'Matemática'],
        keywords: categories.slice(0, 5),
        language: 'en',
        sources: [source],
        sourceDetails: {
          arXiv: {
            externalId: arxivId,
            url: `https://arxiv.org/abs/${arxivId}`
          }
        },
        urls: {
          doiUrl: doi ? `https://doi.org/${doi}` : undefined,
          pdfUrl: pdfUrl || undefined,
          landingPage: `https://arxiv.org/abs/${arxivId}`
        },
        score: {
          bm25: 0,
          morphologicalMatch: 0,
          finalRelevance: 0,
          matchedTerms: []
        }
      });
    }

    return {
      source,
      articles,
      status: 'ok',
      responseTimeMs: Date.now() - startTime
    };
  } catch (err: any) {
    return handleSourceCatchError(source, err, startTime);
  }
}

// 6. Coletor DOAJ (Diretorio de Revistas em Acesso Aberto)
async function harvestDOAJ(query: string): Promise<FetchSourceResult> {
  const startTime = Date.now();
  const source: AcademicSource = 'DOAJ';
  try {
    const url = `https://doaj.org/api/v2/search/articles/${encodeURIComponent(query)}?pageSize=25`;
    const res = await fetchWithTimeout(url);
    if (!res.ok) return handleSourceResponseError(source, res, startTime);
    const data = await res.json();

    const articles: UnifiedArticle[] = (data.results || []).map((item: any) => {
      const bibjson = item.bibjson || {};
      const doiObj = (bibjson.identifier || []).find((i: any) => i.type === 'doi');
      const doi = normalizeDoi(doiObj?.id);

      const authors = (bibjson.author || []).map((a: any) => ({
        name: a.name || 'Desconhecido',
        affiliation: a.affiliation,
        orcid: a.orcid_id
      }));

      const fulltextLink = (bibjson.link || []).find((l: any) => l.type === 'fulltext')?.url;

      return {
        id: `doaj-${item.id || Math.random().toString(36).substring(2, 9)}`,
        doi,
        title: bibjson.title || 'Sem título',
        authors,
        year: bibjson.year ? parseInt(bibjson.year, 10) : null,
        abstract: bibjson.abstract || '',
        venue: bibjson.journal?.title,
        volume: bibjson.journal?.volume,
        issue: bibjson.journal?.number,
        publisher: bibjson.journal?.publisher,
        publicationType: 'journal-article',
        openAccess: {
          isOpen: true,
          status: 'gold',
          pdfUrl: fulltextLink || null,
          license: bibjson.journal?.license?.[0]?.type
        },
        citationCount: 0,
        fieldsOfStudy: (bibjson.subject || []).map((s: any) => s.term).slice(0, 4),
        keywords: (bibjson.keywords || []).slice(0, 5),
        language: bibjson.journal?.language?.[0] || 'pt',
        sources: [source],
        sourceDetails: {
          DOAJ: {
            externalId: item.id,
            url: `https://doaj.org/article/${item.id}`
          }
        },
        urls: {
          doiUrl: doi ? `https://doi.org/${doi}` : undefined,
          pdfUrl: fulltextLink,
          landingPage: `https://doaj.org/article/${item.id}`
        },
        score: {
          bm25: 0,
          morphologicalMatch: 0,
          finalRelevance: 0,
          matchedTerms: []
        }
      };
    });

    return {
      source,
      articles,
      status: 'ok',
      responseTimeMs: Date.now() - startTime
    };
  } catch (err: any) {
    return handleSourceCatchError(source, err, startTime);
  }
}

// 7. Coletor CORE (rede internacional agregadora de repositorios)
async function harvestCORE(query: string): Promise<FetchSourceResult> {
  const startTime = Date.now();
  const source: AcademicSource = 'CORE';
  try {
    const url = `https://api.core.ac.uk/v3/search/works?q=${encodeURIComponent(query)}&limit=25`;
    const res = await fetchWithTimeout(url);
    if (!res.ok) return handleSourceResponseError(source, res, startTime);
    const data = await res.json();

    const articles: UnifiedArticle[] = (data.results || []).map((item: any) => {
      const doi = normalizeDoi(item.doi);
      const authors = (item.authors || []).map((a: any) => ({
        name: typeof a === 'string' ? a : (a.name || 'Desconhecido')
      }));

      return {
        id: `core-${item.id || Math.random().toString(36).substring(2, 9)}`,
        doi,
        title: item.title || 'Sem título',
        authors,
        year: item.yearPublished || null,
        abstract: item.abstract || '',
        venue: item.journals?.[0]?.title || item.publisher,
        publicationType: 'journal-article',
        openAccess: {
          isOpen: true,
          status: 'green',
          pdfUrl: item.downloadUrl || null
        },
        citationCount: item.citationCount || 0,
        fieldsOfStudy: (item.topics || []).slice(0, 4),
        keywords: (item.topics || []).slice(0, 5),
        language: item.language?.code || 'en',
        sources: [source],
        sourceDetails: {
          CORE: {
            externalId: String(item.id),
            url: `https://core.ac.uk/works/${item.id}`
          }
        },
        urls: {
          doiUrl: doi ? `https://doi.org/${doi}` : undefined,
          pdfUrl: item.downloadUrl,
          landingPage: `https://core.ac.uk/works/${item.id}`
        },
        score: {
          bm25: 0,
          morphologicalMatch: 0,
          finalRelevance: 0,
          matchedTerms: []
        }
      };
    });

    return {
      source,
      articles,
      status: 'ok',
      responseTimeMs: Date.now() - startTime
    };
  } catch (err: any) {
    return handleSourceCatchError(source, err, startTime);
  }
}

// 8. Portal CAPES Harvester (Catálogo de Teses e Dissertações / BDTD / Fundo CAPES)
async function harvestCAPES(query: string): Promise<FetchSourceResult> {
  const startTime = Date.now();
  const source: AcademicSource = 'Portal CAPES';
  try {
    const bdtdUrl = `https://bdtd.ibict.br/vufind/api/v1/search?lookfor=${encodeURIComponent(query)}&type=AllFields&limit=25`;
    const crossrefCapesUrl = `https://api.crossref.org/works?query=${encodeURIComponent(query)}&filter=funder:501100002322&rows=25&mailto=academic-search@unila.edu.br`;

    const [bdtdRes, crossrefRes] = await Promise.allSettled([
      fetchWithTimeout(bdtdUrl, {}, 4500),
      fetchWithTimeout(crossrefCapesUrl, {}, 4500)
    ]);

    const articles: UnifiedArticle[] = [];

    // 1. Processa registros da BDTD / CAPES (Teses e Dissertacoes)
    if (bdtdRes.status === 'fulfilled' && bdtdRes.value.ok) {
      try {
        const data = await bdtdRes.value.json();
        const records = data.records || [];
        for (const item of records) {
          const authorsList: { name: string; affiliation?: string }[] = [];
          if (item.authors?.primary) {
            for (const authorName of Object.keys(item.authors.primary)) {
              authorsList.push({ name: authorName.replace(/,\s*/g, ' ').trim() });
            }
          }
          if (item.authors?.secondary) {
            for (const authorName of Object.keys(item.authors.secondary)) {
              if (authorsList.length < 5) {
                authorsList.push({ name: authorName.replace(/,\s*/g, ' ').trim() });
              }
            }
          }
          if (authorsList.length === 0) {
            authorsList.push({ name: 'Pesquisador(a) Pós-Graduação CAPES' });
          }

          const fields: string[] = [];
          const keywords: string[] = [];
          if (Array.isArray(item.subjects)) {
            for (const s of item.subjects) {
              const text = Array.isArray(s) ? s[0] : String(s);
              if (text.includes('CNPQ::') || text.includes('::')) {
                fields.push(text.replace(/CNPQ::/g, '').replace(/::/g, ' - '));
              } else {
                keywords.push(text);
              }
            }
          }

          const primaryUrl = item.urls?.[0]?.url;
          const isThesis = item.formats?.includes('doctoralThesis') || item.formats?.includes('masterThesis') || item.formats?.includes('thesis');
          const pubType: UnifiedArticle['publicationType'] = isThesis ? 'thesis' : 'journal-article';
          const portalCapesLink = `https://www.periodicos.capes.gov.br/index.php/acervo/buscador.html?q=${encodeURIComponent(item.title || query)}`;

          articles.push({
            id: `capes-bdtd-${item.id || Math.random().toString(36).substring(2, 9)}`,
            doi: null,
            title: item.title || 'Pesquisa Acadêmica Registrada na CAPES',
            authors: authorsList,
            year: item.year ? parseInt(item.year, 10) : new Date().getFullYear() - 1,
            abstract: (item.title ? `${item.title}. Produção científica catalogada no Banco de Teses e Dissertações da CAPES/MEC.` : ''),
            venue: isThesis ? 'Catálogo de Teses e Dissertações CAPES' : 'Portal de Periódicos CAPES',
            publisher: 'Coordenação de Aperfeiçoamento de Pessoal de Nível Superior (CAPES)',
            publicationType: pubType,
            openAccess: {
              isOpen: true,
              status: 'green',
              pdfUrl: primaryUrl || null
            },
            citationCount: 0,
            fieldsOfStudy: fields.slice(0, 4),
            keywords: keywords.slice(0, 6),
            language: item.languages?.[0] || 'pt',
            sources: [source],
            sourceDetails: {
              'Portal CAPES': {
                externalId: item.id,
                url: primaryUrl || portalCapesLink
              }
            },
            urls: {
              doiUrl: undefined,
              pdfUrl: primaryUrl,
              landingPage: primaryUrl || portalCapesLink
            },
            score: {
              bm25: 0,
              morphologicalMatch: 0,
              finalRelevance: 0,
              matchedTerms: []
            }
          });
        }
      } catch (e) {
        console.warn('Error parsing BDTD CAPES payload:', e);
      }
    }

    // 2. Processa artigos financiados pela CAPES via Crossref
    if (crossrefRes.status === 'fulfilled' && crossrefRes.value.ok) {
      try {
        const data = await crossrefRes.value.json();
        const items = data.message?.items || [];
        for (const item of items) {
          const doi = normalizeDoi(item.DOI);
          const authors = (item.author || []).map((a: any) => ({
            name: [a.given, a.family].filter(Boolean).join(' ') || a.name || 'Desconhecido',
            affiliation: a.affiliation?.[0]?.name,
            orcid: a.ORCID
          }));

          const year = item.published?.['date-parts']?.[0]?.[0] || 
                       item['published-print']?.['date-parts']?.[0]?.[0] || 
                       item['published-online']?.['date-parts']?.[0]?.[0] || null;

          let abstract = (item.abstract || '')
            .replace(/<jats:[^>]+>/g, '')
            .replace(/<\/jats:[^>]+>/g, '')
            .replace(/<[^>]+>/g, '');

          const isOpen = item.license ? true : false;
          const pdfLink = item.link?.find((l: any) => l['content-type'] === 'application/pdf')?.URL;
          const portalCapesLink = doi 
            ? `https://www.periodicos.capes.gov.br/index.php/acervo/buscador.html?q=${encodeURIComponent(doi)}`
            : (item.URL || `https://www.periodicos.capes.gov.br/`);

          articles.push({
            id: `capes-cr-${item.DOI ? item.DOI.replace(/[^a-zA-Z0-9]/g, '') : Math.random().toString(36).substring(2, 9)}`,
            doi,
            title: item.title?.[0] || 'Artigo Fomento CAPES',
            authors,
            year,
            abstract,
            venue: item['container-title']?.[0] ? `${item['container-title']?.[0]} (Fomento CAPES)` : 'Periódico Indexado CAPES',
            volume: item.volume,
            issue: item.issue,
            pages: item.page,
            publisher: item.publisher,
            publicationType: 'journal-article',
            openAccess: {
              isOpen,
              status: isOpen ? 'gold' : 'closed',
              pdfUrl: pdfLink || null,
              license: item.license?.[0]?.URL
            },
            citationCount: item['is-referenced-by-count'] || 0,
            fieldsOfStudy: (item.subject || []).slice(0, 4),
            keywords: ['Fomento CAPES', ...(item.subject || []).slice(0, 5)],
            language: item.language || 'pt',
            sources: [source],
            sourceDetails: {
              'Portal CAPES': {
                externalId: item.DOI,
                url: portalCapesLink
              }
            },
            urls: {
              doiUrl: doi ? `https://doi.org/${doi}` : undefined,
              pdfUrl: pdfLink,
              landingPage: portalCapesLink
            },
            score: {
              bm25: 0,
              morphologicalMatch: 0,
              finalRelevance: 0,
              matchedTerms: []
            }
          });
        }
      } catch (e) {
        console.warn('Error parsing Crossref CAPES payload:', e);
      }
    }

    const bothFailed = (bdtdRes.status === 'rejected' || (bdtdRes.status === 'fulfilled' && !bdtdRes.value.ok)) &&
                       (crossrefRes.status === 'rejected' || (crossrefRes.status === 'fulfilled' && !crossrefRes.value.ok));

    if (articles.length === 0 && bothFailed) {
      const isRate = (bdtdRes.status === 'fulfilled' && bdtdRes.value.status === 429) || (crossrefRes.status === 'fulfilled' && crossrefRes.value.status === 429);
      const isTimeout = (bdtdRes.status === 'rejected' && (bdtdRes.reason?.name === 'AbortError' || bdtdRes.reason?.message?.includes('timeout'))) ||
                        (crossrefRes.status === 'rejected' && (crossrefRes.reason?.name === 'AbortError' || crossrefRes.reason?.message?.includes('timeout')));

      return {
        source,
        articles: [],
        status: isRate ? 'rate-limited' : isTimeout ? 'timeout' : 'error',
        responseTimeMs: Date.now() - startTime,
        errorMessage: isRate ? 'Bloqueio temporário (Portal CAPES HTTP 429)' : isTimeout ? 'Tempo limite esgotado (CAPES/BDTD > 4.5s)' : 'Falha nos servidores da CAPES/BDTD',
        errorDetail: isRate
          ? 'Serviços da CAPES/BDTD aplicaram rate limiting temporário de consultas.'
          : isTimeout
            ? 'Servidores da BDTD/IBICT e CAPES não responderam dentro do limite de tempo.'
            : 'Falha de comunicação ou indisponibilidade no catálogo da BDTD/CAPES.'
      };
    }

    return {
      source,
      articles,
      status: 'ok',
      responseTimeMs: Date.now() - startTime
    };
  } catch (err: any) {
    return handleSourceCatchError(source, err, startTime);
  }
}

/**
 * Orquestrador principal de busca federada
 * Consulta simultaneamente os 8 repositórios, gerencia a deduplicação, aplica pontuação BM25 e gera facetas no padrão UNILA
 */
export async function executeFederatedSearch(
  query: string,
  selectedSources: AcademicSource[] = [
    'Portal CAPES',
    'Semantic Scholar',
    'OpenAlex',
    'Crossref',
    'CORE',
    'Europe PMC',
    'arXiv',
    'DOAJ'
  ],
  useSemantic: boolean = false
): Promise<{
  articles: UnifiedArticle[];
  sourcesStatus: FetchSourceResult[];
  facets: SearchFacets;
  deduplicatedCount: number;
  totalFound: number;
}> {
  const harvestPromises: Promise<FetchSourceResult>[] = [];

  if (selectedSources.includes('Portal CAPES')) harvestPromises.push(harvestCAPES(query));
  if (selectedSources.includes('OpenAlex')) harvestPromises.push(harvestOpenAlex(query));
  if (selectedSources.includes('Crossref')) harvestPromises.push(harvestCrossref(query));
  if (selectedSources.includes('Semantic Scholar')) harvestPromises.push(harvestSemanticScholar(query));
  if (selectedSources.includes('Europe PMC')) harvestPromises.push(harvestEuropePMC(query));
  if (selectedSources.includes('arXiv')) harvestPromises.push(harvestArXiv(query));
  if (selectedSources.includes('DOAJ')) harvestPromises.push(harvestDOAJ(query));
  if (selectedSources.includes('CORE')) harvestPromises.push(harvestCORE(query));

  // 1. Executa todas as coletas simultaneamente. O Promise.allSettled garante que
  // uma fonte lenta ou indisponível não impeça a entrega dos resultados das outras fontes.
  const results = await Promise.allSettled(harvestPromises);
  const sourceStatuses: FetchSourceResult[] = [];
  let allRawArticles: UnifiedArticle[] = [];

  for (const res of results) {
    if (res.status === 'fulfilled') {
      sourceStatuses.push(res.value);
      allRawArticles.push(...res.value.articles);
    } else {
      sourceStatuses.push({
        source: 'Outros' as any,
        articles: [],
        status: 'error',
        responseTimeMs: 0,
        errorMessage: res.reason?.message || 'Falha na coleta da base',
        errorDetail: 'Falha interna inesperada durante a execução da busca'
      });
    }
  }

  // DIRETRIZ ESTRITA DE INTEGRIDADE CIENTÍFICA:
  // Nenhum artigo é preparado, simulado ou inserido via corpus de fallback local.
  // Caso uma API falhar ou não achar nada, 0 resultados são retornados.
  const totalFound = allRawArticles.length;

  if (allRawArticles.length === 0) {
    const facets = computeFacets([], sourceStatuses);
    return {
      articles: [],
      sourcesStatus: sourceStatuses,
      facets,
      deduplicatedCount: 0,
      totalFound: 0
    };
  }

  // 2. Desduplicação Canônica:
  // Artigos idênticos encontrados em bases distintas (ex: mesmo DOI no OpenAlex e Crossref)
  // são unificados em um registro único, preservando o melhor abstract e somando as fontes.
  const deduplicated = deduplicateArticles(allRawArticles);

  if (deduplicated.length === 0) {
    const facets = computeFacets([], sourceStatuses);
    return {
      articles: [],
      sourcesStatus: sourceStatuses,
      facets,
      deduplicatedCount: 0,
      totalFound: 0
    };
  }

  // 4. Construção das Estatísticas do Corpus para o Modelo BM25:
  // Para calcular o IDF (Inverse Document Frequency), precisamos contar em quantos documentos
  // cada raiz morfológica aparece e calcular o comprimento médio (avgDocLength) dos textos.
  const totalDocs = Math.max(deduplicated.length, 1);
  const termDocFrequencies = new Map<string, number>();
  let sumDocLengths = 0;

  for (const doc of deduplicated) {
    const docText = `${doc.title} ${doc.abstract} ${doc.keywords.join(' ')} ${doc.authors.map(a => a.name).join(' ')}`;
    const tokens = tokenize(docText);
    sumDocLengths += tokens.stems.length;

    const uniqueDocStems = new Set(tokens.stems);
    for (const stem of uniqueDocStems) {
      termDocFrequencies.set(stem, (termDocFrequencies.get(stem) || 0) + 1);
    }
  }

  const avgDocLength = sumDocLengths / totalDocs;

  // 5. Aplicação do Modelo Probabilístico BM25 + Boost Morfológico e Citacional:
  // Cada artigo recebe uma pontuação calculada dinamicamente, gerando o `% Relevância` (15% a 99%).
  const scoredArticles = deduplicated.map(doc => {
    const score = calculateBM25Score(
      query,
      {
        id: doc.id,
        title: doc.title,
        abstract: doc.abstract,
        keywords: doc.keywords,
        fieldsOfStudy: doc.fieldsOfStudy,
        authors: doc.authors.map(a => a.name),
        citationCount: doc.citationCount
      },
      avgDocLength,
      totalDocs,
      termDocFrequencies,
      useSemantic
    );

    return {
      ...doc,
      score
    };
  });

  // Ordena por relevancia final decrescente
  scoredArticles.sort((a, b) => b.score.finalRelevance - a.score.finalRelevance);

  // Calcula Facetas no padrao institucional UNILA
  const facets = computeFacets(scoredArticles, sourceStatuses);

  return {
    articles: scoredArticles,
    sourcesStatus: sourceStatuses,
    facets,
    deduplicatedCount: scoredArticles.length,
    totalFound
  };
}

/**
 * Constroi agregacoes multifacetadas inspiradas no portal institucional da UNILA
 */
function computeFacets(articles: UnifiedArticle[], sourceStatuses: FetchSourceResult[]): SearchFacets {
  const yearCounts = new Map<number, number>();
  const authorCounts = new Map<string, number>();
  const fieldCounts = new Map<string, number>();
  const keywordCounts = new Map<string, number>();
  const langCounts = new Map<string, number>();
  const typeCounts = new Map<string, number>();
  const oaCounts = new Map<string, number>();
  const sourceCounts = new Map<AcademicSource, number>();

  for (const a of articles) {
    // Ano
    if (a.year) {
      yearCounts.set(a.year, (yearCounts.get(a.year) || 0) + 1);
    }

    // Autores
    for (const author of a.authors.slice(0, 3)) {
      if (author.name && author.name !== 'Desconhecido') {
        authorCounts.set(author.name, (authorCounts.get(author.name) || 0) + 1);
      }
    }

    // Areas do conhecimento
    for (const f of a.fieldsOfStudy) {
      fieldCounts.set(f, (fieldCounts.get(f) || 0) + 1);
    }

    // Palavras-chave
    for (const k of a.keywords) {
      keywordCounts.set(k, (keywordCounts.get(k) || 0) + 1);
    }

    // Idioma
    const lang = a.language || 'en';
    langCounts.set(lang, (langCounts.get(lang) || 0) + 1);

    // Tipo de Publicacao
    typeCounts.set(a.publicationType, (typeCounts.get(a.publicationType) || 0) + 1);

    // Acesso Aberto
    const oaKey = a.openAccess.isOpen ? (a.openAccess.status || 'gold') : 'closed';
    oaCounts.set(oaKey, (oaCounts.get(oaKey) || 0) + 1);

    // Fontes academicas
    for (const s of a.sources) {
      sourceCounts.set(s, (sourceCounts.get(s) || 0) + 1);
    }
  }

  const mapToSortedFacet = (map: Map<string, number>, labelMapper?: (v: string) => string): FacetItem[] => {
    return Array.from(map.entries())
      .map(([val, count]) => ({
        value: val,
        label: labelMapper ? labelMapper(val) : val,
        count
      }))
      .sort((a, b) => b.count - a.count);
  };

  const years = Array.from(yearCounts.entries())
    .map(([year, count]) => ({ year, count }))
    .sort((a, b) => b.year - a.year);

  const langLabels: Record<string, string> = {
    pt: 'Português',
    es: 'Español (Espanhol)',
    en: 'English (Inglês)',
    fr: 'Français (Francês)',
    de: 'Deutsch (Alemão)',
    it: 'Italiano'
  };

  const typeLabels: Record<string, string> = {
    'journal-article': 'Artigo de Periódico',
    'proceedings-article': 'Artigo de Evento / Anais',
    'preprint': 'Preprint (arXiv / SSRN)',
    'thesis': 'Tese / Dissertação',
    'book-chapter': 'Livro / Capítulo',
    'review': 'Revisão Sistemática',
    'other': 'Outros Documentos'
  };

  const oaLabels: Record<string, string> = {
    gold: 'Ouro (Gold OA - Direto na Revista)',
    green: 'Verde (Green OA - Repositório Institucional)',
    bronze: 'Bronze (Acesso Livre na Editora)',
    hybrid: 'Híbrido (Periódico Pago com Artigo OA)',
    closed: 'Acesso Restrito / Assinatura'
  };

  const allSources: AcademicSource[] = [
    'Portal CAPES',
    'Semantic Scholar',
    'OpenAlex',
    'Crossref',
    'CORE',
    'Europe PMC',
    'arXiv',
    'DOAJ'
  ];

  const sourceFacet = allSources.map(s => {
    const statusObj = sourceStatuses.find(st => st.source === s);
    return {
      source: s,
      count: sourceCounts.get(s) || 0,
      available: statusObj ? statusObj.status === 'ok' : true
    };
  });

  return {
    years,
    authors: mapToSortedFacet(authorCounts).slice(0, 15),
    fields: mapToSortedFacet(fieldCounts).slice(0, 15),
    keywords: mapToSortedFacet(keywordCounts).slice(0, 20),
    languages: mapToSortedFacet(langCounts, v => langLabels[v] || v.toUpperCase()),
    publicationTypes: mapToSortedFacet(typeCounts, v => typeLabels[v] || v),
    openAccess: mapToSortedFacet(oaCounts, v => oaLabels[v] || v),
    sources: sourceFacet
  };
}
